import { Component, JSX, onMount, onCleanup, splitProps } from 'solid-js';

export interface SpotlightCardProps extends JSX.HTMLAttributes<HTMLDivElement> {
  radius?: number;
  color?: string;
  borderColor?: string;
  opacity?: number;
  spread?: number;
  mode?: 'both' | 'border' | 'background';
  smoothing?: number;
  disabled?: boolean;
  class?: string;
  children?: JSX.Element;
}

export const SpotlightCard: Component<SpotlightCardProps> = (props) => {
  const [local, others] = splitProps(props, [
    'radius',
    'color',
    'borderColor',
    'opacity',
    'spread',
    'mode',
    'smoothing',
    'disabled',
    'class',
    'children',
  ]);

  let cardRef: HTMLDivElement | undefined;
  let rect: { left: number; top: number; width: number; height: number } | null = null;

  let targetX = -9999;
  let targetY = -9999;
  let currentX = -9999;
  let currentY = -9999;
  let currentOpacity = 0;
  let targetOpacity = 0;
  let isHovered = false;
  let rafId: number | null = null;
  let isReducedMotion = false;

  const radius = () => local.radius ?? 350;
  const color = () => local.color ?? '#6366f1';
  const borderColor = () => local.borderColor ?? '#818cf8';
  const opacity = () => local.opacity ?? 0.85;
  const spread = () => local.spread ?? 60;
  const mode = () => local.mode ?? 'both';
  const smoothing = () => local.smoothing ?? 0.2;
  const disabled = () => local.disabled ?? false;

  const measureRect = () => {
    if (!cardRef) return;
    const r = cardRef.getBoundingClientRect();
    rect = { left: r.left, top: r.top, width: r.width, height: r.height };
  };

  const updateFrame = () => {
    if (!cardRef) return;

    if (disabled() || isReducedMotion) {
      cardRef.style.setProperty('--exhuma-spotlight-opacity', '0');
      rafId = null;
      return;
    }

    const factor = Math.max(0.05, Math.min(1, smoothing()));
    currentX += (targetX - currentX) * factor;
    currentY += (targetY - currentY) * factor;
    currentOpacity += (targetOpacity - currentOpacity) * Math.max(0.08, factor * 0.75);

    cardRef.style.setProperty('--exhuma-spotlight-x', `${currentX.toFixed(2)}px`);
    cardRef.style.setProperty('--exhuma-spotlight-y', `${currentY.toFixed(2)}px`);
    cardRef.style.setProperty('--exhuma-spotlight-opacity', `${currentOpacity.toFixed(3)}`);

    const diffX = Math.abs(targetX - currentX);
    const diffY = Math.abs(targetY - currentY);
    const diffOp = Math.abs(targetOpacity - currentOpacity);

    if (diffX > 0.1 || diffY > 0.1 || diffOp > 0.005 || isHovered) {
      rafId = requestAnimationFrame(updateFrame);
    } else {
      rafId = null;
    }
  };

  const scheduleRaf = () => {
    if (rafId === null) {
      rafId = requestAnimationFrame(updateFrame);
    }
  };

  const onPointerEnter = (e: PointerEvent) => {
    if (disabled() || isReducedMotion) return;
    isHovered = true;
    measureRect();
    if (rect) {
      targetX = e.clientX - rect.left;
      targetY = e.clientY - rect.top;
      targetOpacity = opacity();
      if (currentX < -1000) {
        currentX = targetX;
        currentY = targetY;
      }
    }
    scheduleRaf();
  };

  const onPointerMove = (e: PointerEvent) => {
    if (disabled() || isReducedMotion) return;
    if (!rect) measureRect();
    if (!rect) return;
    targetX = e.clientX - rect.left;
    targetY = e.clientY - rect.top;
    targetOpacity = opacity();
    scheduleRaf();
  };

  const onPointerLeave = () => {
    isHovered = false;
    targetOpacity = 0;
    scheduleRaf();
  };

