import React, { useRef } from 'react';
import {
  View,
  StyleSheet,
  PanResponder,
  Animated,
  type ViewProps,
  type LayoutChangeEvent,
} from 'react-native';

export interface SpotlightCardProps extends ViewProps {
  radius?: number;
  color?: string;
  borderColor?: string;
  opacity?: number;
  spread?: number;
  mode?: 'both' | 'border' | 'background';
  smoothing?: number;
  disabled?: boolean;
  children?: React.ReactNode;
}

export function SpotlightCard({
  radius = 350,
  color = '#6366f1',
  borderColor = '#818cf8',
  opacity = 0.85,
  spread = 60,
  mode = 'both',
  smoothing = 0.2,
  disabled = false,
  children,
  style,
  ...props
}: SpotlightCardProps) {
  const dimensions = useRef({ width: 0, height: 0 }).current;
  const spotlightPos = useRef(new Animated.ValueXY({ x: 0, y: 0 })).current;
  const spotlightOpacity = useRef(new Animated.Value(0)).current;

  const onLayout = (e: LayoutChangeEvent) => {
    const { width, height } = e.nativeEvent.layout;
    dimensions.width = width;
    dimensions.height = height;
  };

  const panResponder = useRef(
    PanResponder.create({
      onStartShouldSetPanResponder: () => !disabled,
      onMoveShouldSetPanResponder: () => !disabled,
      onPanResponderGrant: (evt) => {
        if (disabled) return;
        const { locationX, locationY } = evt.nativeEvent;
        spotlightPos.setValue({ x: locationX - radius, y: locationY - radius });
        Animated.timing(spotlightOpacity, {
          toValue: opacity,
          duration: 150,
          useNativeDriver: false,
        }).start();
      },
      onPanResponderMove: (evt) => {
        if (disabled) return;
        const { locationX, locationY } = evt.nativeEvent;
        if (smoothing <= 0 || smoothing >= 1) {
          spotlightPos.setValue({ x: locationX - radius, y: locationY - radius });
        } else {
          Animated.spring(spotlightPos, {
            toValue: { x: locationX - radius, y: locationY - radius },
            friction: 7,
            tension: 50,
            useNativeDriver: false,
          }).start();
        }
      },
      onPanResponderRelease: () => {
        Animated.timing(spotlightOpacity, {
          toValue: 0,
          duration: 300,
          useNativeDriver: false,
        }).start();
      },
    })
  ).current;

  const showGlow = mode === 'both' || mode === 'background';
  const showBorder = mode === 'both' || mode === 'border';

  return (
    <View
      onLayout={onLayout}
      {...panResponder.panHandlers}
      style={[styles.container, style]}
      {...props}
    >
      {showGlow && (
        <Animated.View
          pointerEvents="none"
          style={[
            styles.spotlight,
            {
              width: radius * 2,
              height: radius * 2,
              borderRadius: radius,
              backgroundColor: color,
              opacity: spotlightOpacity,
              transform: spotlightPos.getTranslateTransform(),
            },
          ]}
        />
      )}
      {showBorder && (
        <Animated.View
          pointerEvents="none"
          style={[
            StyleSheet.absoluteFillObject,
            styles.borderOverlay,
            {
              borderColor: borderColor,
              opacity: spotlightOpacity,
            },
          ]}
        />
      )}
      <View style={styles.content}>{children}</View>
    </View>
  );
}

const styles = StyleSheet.create({
  container: {
    position: 'relative',
    overflow: 'hidden',
    borderRadius: 20,
    borderWidth: 1,
    borderColor: 'rgba(255, 255, 255, 0.1)',
    backgroundColor: 'rgba(23, 23, 23, 0.6)',
  },
  spotlight: {
    position: 'absolute',
    top: 0,
    left: 0,
  },
  borderOverlay: {
    borderWidth: 1.5,
    borderRadius: 20,
  },
  content: {
    position: 'relative',
    zIndex: 1,
  },
});

